{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "inventory",
      "host": "inventory.internal",
      "port": 7997,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 9916,
      "weight": 7,
      "health_check": "/healthz"
    },
    {
      "name": "pricing",
      "host": "pricing.internal",
      "port": 8878,
      "weight": 3,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 8152,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 9664,
      "weight": 5,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/accounts/summary",
      "upstream": "accounts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/export",
      "upstream": "accounts",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/accounts/audit",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 0
    },
    {
      "path": "/api/v1/pricing/audit",
      "upstream": "pricing",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/inventory/batch",
      "upstream": "inventory",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/pricing/lookup",
      "upstream": "pricing",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2000,
      "retries": 2
    },
    {
      "path": "/api/v1/accounts/events",
      "upstream": "accounts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 2
    },
    {
      "path": "/api/v1/pricing/settings",
      "upstream": "pricing",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2500,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/items",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 2000,
      "retries": 3
    }
  ]
}

